/**
 * Lender policy engine. Evaluates the simulated RBC / TD / CIBC decision rules
 * (data/hackathon/policies/*.md) against client facts that come ONLY from governed,
 * advisor-confirmed `financial_fact` memories the current user is allowed to read.
 *
 * The decision is computed in code, not generated by a model. That is what lets us
 * measure a memory's influence exactly: remove one fact and recompute (see pivotalFacts).
 *
 * Thresholds, caps, coefficients and auto-decline conditions are read from the policy
 * documents. The semantics of each product (which ratio feeds which gate) live here.
 */

export type LenderProduct = "mortgage" | "personal_line_of_credit" | "business_credit_card";

export interface LenderPolicy {
  _id: string; // policy_id
  bank: string;
  product: LenderProduct;
  version: string;
  effectiveDate: string;
  status: string;
  simulated: boolean;
  decisionRules: Record<string, unknown>;
  sourceFile: string;
  contentHash: string;
}

/** Vocabulary of fact keys the engine understands. Extractors are told to use these keys. */
export const FACT_KEYS = {
  credit_score: "Exact credit score (restricted: credit adjudication only)",
  credit_score_band_min: "Lower bound of the credit score band the advisor may see",
  credit_score_band_max: "Upper bound of the credit score band the advisor may see",
  annual_income: "Documented annual income used by lenders (CAD)",
  housing_cost_monthly: "Current monthly housing cost: mortgage, property tax, heating (CAD)",
  monthly_debt_payments: "Other monthly debt payments (CAD)",
  property_equity: "Home equity (CAD)",
  investable_assets_at_cibc: "Investable assets held at CIBC (CAD)",
  cibc_deposit_balance: "Deposits held at CIBC (CAD)",
  primary_business_account_at_cibc: "1 if CIBC is the primary business account",
  months_in_business: "Months the business has operated",
  annual_business_revenue: "Annual business revenue (CAD)",
  business_debt: "Existing business debt, including guaranteed debt (CAD)",
  bankruptcy_last_months: "Months since a bankruptcy (omit if none)",
  foreclosure_last_months: "Months since a foreclosure (omit if none)",
  requested_line_amount: "Line of credit amount requested (CAD)",
  mortgage_down_payment_pct: "Down payment on the requested mortgage, as a fraction",
  mortgage_stressed_gds: "GDS of the requested mortgage at the stress-test rate, documented income only",
  mortgage_stressed_tds: "TDS of the requested mortgage at the stress-test rate, documented income only",
} as const;
export type FactKey = keyof typeof FACT_KEYS;

export interface Fact {
  key: string;
  value: number;
  memoryId?: string;
  lineageId?: string;
  version?: number;
  statement?: string;
}
export type Facts = Record<string, Fact>;

export type Decision = "approve" | "refer" | "decline";
export type CheckOutcome = "pass" | "fail" | "unknown";

export interface Check {
  rule: string;
  outcome: CheckOutcome;
  detail: string;
  factKeys: string[];
}

export interface PivotalFact {
  factKey: string;
  memoryId?: string;
  statement?: string;
  decisionWithout: Decision;
}

export interface LenderCheck {
  policyId: string;
  bank: string;
  product: LenderProduct;
  policyVersion: string;
  decision: Decision;
  summary: string;
  checks: Check[];
  offer?: { kind: string; limit?: number; note?: string };
  factsUsed: { key: string; value: number; memoryId?: string; version?: number }[];
  /** Counterfactual: facts whose removal changes this decision. Computed by re-running the engine. */
  pivotalFacts: PivotalFact[];
}

// ---------- tiny, safe policy-expression helpers ----------

const OPS: Record<string, (a: number, b: number) => boolean> = {
  "<": (a, b) => a < b,
  "<=": (a, b) => a <= b,
  ">": (a, b) => a > b,
  ">=": (a, b) => a >= b,
};

/** "credit_score < 620" → { ident, op, value }. Anything else is rejected. */
export function parseCondition(s: string) {
  const m = /^\s*([a-z_]+)\s*(<=|>=|<|>)\s*([0-9.]+)\s*$/.exec(s);
  if (!m) throw new Error(`Unsupported policy condition: ${s}`);
  return { ident: m[1], op: m[2], value: Number(m[3]) };
}

/** "0.50 * annual_income" or "investable_assets_at_cibc / 180" → evaluator. */
export function parseLinear(s: string) {
  const mul = /^\s*([0-9.]+)\s*\*\s*([a-z_]+)\s*$/.exec(s);
  if (mul) return { ident: mul[2], apply: (x: number) => Number(mul[1]) * x };
  const div = /^\s*([a-z_]+)\s*\/\s*([0-9.]+)\s*$/.exec(s);
  if (div) return { ident: div[1], apply: (x: number) => x / Number(div[2]) };
  throw new Error(`Unsupported policy formula: ${s}`);
}

const num = (r: Record<string, unknown>, k: string) => (typeof r[k] === "number" ? (r[k] as number) : undefined);
const obj = (r: Record<string, unknown>, k: string) =>
  r[k] && typeof r[k] === "object" ? (r[k] as Record<string, unknown>) : undefined;
const money = (n: number) => `$${Math.round(n).toLocaleString("en-CA")}`;
const pct = (n: number) => `${(n * 100).toFixed(1)}%`;

/** Facts that default when absent (absence means "none on file"), so they never block a decision. */
const OPTIONAL_DEFAULTS: Record<string, number> = {
  investable_assets_at_cibc: 0,
  cibc_deposit_balance: 0,
  primary_business_account_at_cibc: 0,
  bankruptcy_last_months: Number.POSITIVE_INFINITY,
  foreclosure_last_months: Number.POSITIVE_INFINITY,
  monthly_debt_payments: 0,
  housing_cost_monthly: 0,
  property_equity: 0,
};

class Ctx {
  used = new Set<string>();
  constructor(private facts: Facts) {}
  has(k: string) {
    return k in this.facts;
  }
  get(k: string): number | undefined {
    if (k in this.facts) {
      this.used.add(k);
      return this.facts[k].value;
    }
    if (k in OPTIONAL_DEFAULTS) return OPTIONAL_DEFAULTS[k];
    return undefined;
  }
}

/** Credit-score comparisons work on the exact score if readable, otherwise on the visible band. */
function scoreTest(ctx: Ctx, op: string, threshold: number): { outcome: boolean | null; detail: string; keys: string[] } {
  const exact = ctx.get("credit_score");
  if (exact !== undefined) {
    return { outcome: OPS[op](exact, threshold), detail: `score ${exact}`, keys: ["credit_score"] };
  }
  const lo = ctx.get("credit_score_band_min");
  const hi = ctx.get("credit_score_band_max") ?? 900;
  if (lo === undefined) return { outcome: null, detail: "no credit score or band on file", keys: [] };
  const keys = ["credit_score_band_min", ...(ctx.has("credit_score_band_max") ? ["credit_score_band_max"] : [])];
  const a = OPS[op](lo, threshold);
  const b = OPS[op](hi, threshold);
  if (a === b) return { outcome: a, detail: `band ${lo}–${hi}`, keys };
  return {
    outcome: null,
    detail: `band ${lo}–${hi} straddles ${threshold}; exact score is restricted to credit adjudication`,
    keys,
  };
}

function autoDeclines(ctx: Ctx, rules: Record<string, unknown>, derived: Record<string, number | undefined>): Check[] {
  const conds = (rules.auto_decline_if as string[] | undefined) ?? [];
  return conds.map((raw) => {
    const c = parseCondition(raw);
    if (c.ident === "credit_score" || c.ident === "principal_credit_score") {
      const t = scoreTest(ctx, c.op, c.value);
      return {
        rule: `Auto-decline if ${raw}`,
        outcome: t.outcome === null ? "unknown" : t.outcome ? "fail" : "pass",
        detail: t.detail,
        factKeys: t.keys,
      } satisfies Check;
    }
    const v = c.ident in derived ? derived[c.ident] : ctx.get(c.ident);
    if (v === undefined) return { rule: `Auto-decline if ${raw}`, outcome: "unknown", detail: `${c.ident} not on file`, factKeys: [] };
    const hit = OPS[c.op](v, c.value);
    return {
      rule: `Auto-decline if ${raw}`,
      outcome: hit ? "fail" : "pass",
      detail: Number.isFinite(v) ? `${c.ident} = ${v < 2 && v > 0 ? pct(v) : v.toLocaleString("en-CA")}` : `no ${c.ident.replace(/_last_months$/, "")} on file`,
      factKeys: Number.isFinite(v) && ctx.has(c.ident) ? [c.ident] : [],
    } satisfies Check;
  });
}

function minCheck(rule: string, actual: number | undefined, min: number, key: string, fmt = money): Check {
  if (actual === undefined) return { rule, outcome: "unknown", detail: `${key} not on file`, factKeys: [] };
  return { rule, outcome: actual >= min ? "pass" : "fail", detail: `${fmt(actual)} vs minimum ${fmt(min)}`, factKeys: [key] };
}
function maxCheck(rule: string, actual: number | undefined, max: number, keys: string[], missing: string): Check {
  if (actual === undefined) return { rule, outcome: "unknown", detail: missing, factKeys: [] };
  return { rule, outcome: actual <= max ? "pass" : "fail", detail: `${pct(actual)} vs maximum ${pct(max)}`, factKeys: keys };
}
function scoreMin(ctx: Ctx, min: number, label = "Credit score"): Check {
  const t = scoreTest(ctx, ">=", min);
  return {
    rule: `${label} ≥ ${min}`,
    outcome: t.outcome === null ? "unknown" : t.outcome ? "pass" : "fail",
    detail: t.detail,
    factKeys: t.keys,
  };
}

function decide(checks: Check[]): Decision {
  if (checks.some((c) => c.outcome === "fail")) return "decline";
  if (checks.some((c) => c.outcome === "unknown")) return "refer";
  return "approve";
}

// ---------- products ----------

interface Evaluated {
  checks: Check[];
  offer?: LenderCheck["offer"];
  applicable: boolean;
  notApplicableReason?: string;
}

function evalMortgage(p: LenderPolicy, ctx: Ctx): Evaluated {
  const r = p.decisionRules;
  if (!ctx.has("mortgage_stressed_tds") && !ctx.has("mortgage_down_payment_pct")) {
    return { checks: [], applicable: false, notApplicableReason: "No mortgage request on file." };
  }
  const income = ctx.get("annual_income");
  const assetIncomeAllowed = r.asset_based_income_allowed === true;
  const assetsAtCibc = ctx.get("investable_assets_at_cibc") ?? 0;
  let assetIncome = 0;
  const abi = obj(r, "asset_based_income");
  if (assetIncomeAllowed && abi && typeof abi.formula === "string" && assetsAtCibc > 0) {
    assetIncome = parseLinear(abi.formula).apply(assetsAtCibc) * 12; // formula gives a monthly equivalent
  }
  const qualifying = income === undefined ? undefined : income + assetIncome;
  const scale = income && qualifying ? income / qualifying : 1; // ratios on file use documented income only
  const gds = ctx.get("mortgage_stressed_gds");
  const tds = ctx.get("mortgage_stressed_tds");
  const dp = ctx.get("mortgage_down_payment_pct");
  const checks: Check[] = [...autoDeclines(ctx, r, { down_payment_pct: dp })];
  checks.push(scoreMin(ctx, num(r, "min_credit_score")!));
  const minInc = num(r, "min_annual_income")!;
  const incCheck = minCheck("Qualifying income", qualifying, minInc, "annual_income");
  if (assetIncome > 0) {
    incCheck.detail += ` (includes ${money(assetIncome)}/yr asset-based income from ${money(assetsAtCibc)} at CIBC)`;
    incCheck.factKeys.push("investable_assets_at_cibc");
  }
  checks.push(incCheck);
  const assetKeys = assetIncome > 0 ? ["investable_assets_at_cibc", "annual_income"] : [];
  if (gds !== undefined || num(r, "max_gds") === undefined) {
    if (num(r, "max_gds") !== undefined)
      checks.push(maxCheck("GDS at stress-test rate", gds! * scale, num(r, "max_gds")!, ["mortgage_stressed_gds", ...assetKeys], ""));
  } else {
    checks.push({ rule: "GDS at stress-test rate", outcome: "pass", detail: "GDS for this request not on file; not checked", factKeys: [] });
  }
  checks.push(maxCheck("TDS at stress-test rate", tds === undefined ? undefined : tds * scale, num(r, "max_tds")!, ["mortgage_stressed_tds", ...assetKeys], "TDS for this request not on file"));
  let minDp = num(r, "min_down_payment_pct")!;
  const altDp = num(r, "min_down_payment_pct_if_assets_ge_500000");
  if (altDp !== undefined && assetsAtCibc >= 500000) minDp = altDp;
  checks.push(minCheck("Down payment", dp, minDp, "mortgage_down_payment_pct", pct));
  return { checks, applicable: true };
}

function evalPlc(p: LenderPolicy, ctx: Ctx): Evaluated {
  const r = p.decisionRules;
  const requested = ctx.get("requested_line_amount");
  if (requested === undefined) return { checks: [], applicable: false, notApplicableReason: "No line of credit request on file." };
  const income = ctx.get("annual_income");
  const assets = ctx.get("investable_assets_at_cibc") ?? 0;
  const housing = ctx.get("housing_cost_monthly") ?? 0;
  const debts = ctx.get("monthly_debt_payments") ?? 0;
  // New line's required payment assumed at 3% of the limit per month (lender rule of thumb used in the profiles).
  const tdsAfter = income ? (housing + debts + 0.03 * requested) / (income / 12) : undefined;
  const checks: Check[] = autoDeclines(ctx, r, { tds_after_new_limit: tdsAfter });
  checks.push(scoreMin(ctx, num(r, "min_credit_score")!));
  const minInc = num(r, "min_annual_income")!;
  if (p.bank === "CIBC" && assets >= 250000) {
    checks.push({ rule: "Income floor", outcome: "pass", detail: `waived: ${money(assets)} invested at CIBC`, factKeys: ["investable_assets_at_cibc"] });
  } else {
    checks.push(minCheck("Income floor", income, minInc, "annual_income"));
  }
  checks.push(
    maxCheck("TDS with new line (3% payment)", tdsAfter, num(r, "max_tds")!, ["annual_income", "requested_line_amount", "housing_cost_monthly", "monthly_debt_payments"].filter((k) => ctx.has(k)), "income not on file"),
  );
  let offer: LenderCheck["offer"];
  const inv = obj(r, "investment_secured");
  if (inv && typeof inv.available_if === "string" && typeof inv.limit_formula === "string") {
    const cond = parseCondition(inv.available_if);
    if (OPS[cond.op](assets, cond.value)) {
      const lim = Math.min(parseLinear(inv.limit_formula).apply(assets), (inv.cap as number) ?? Infinity);
      offer = { kind: "investment-secured line", limit: Math.min(requested, lim), note: `up to ${money(lim)} against ${money(assets)} at CIBC` };
    }
  }
  const uns = obj(r, "unsecured");
  if (!offer && uns && typeof uns.limit_formula === "string" && income !== undefined) {
    const raw = parseLinear(uns.limit_formula).apply(income);
    const lim = Math.min(raw, (uns.cap as number) ?? Infinity);
    const floor = (uns.floor as number) ?? 0;
    if (lim < floor) checks.push({ rule: "Unsecured limit floor", outcome: "fail", detail: `${money(lim)} below floor ${money(floor)}`, factKeys: ["annual_income"] });
    offer = { kind: "unsecured line", limit: Math.min(requested, lim), note: `policy maximum ${money(lim)}` };
  }
  const sec = obj(r, "secured");
  const equity = ctx.get("property_equity") ?? 0;
  if (sec && equity > 0 && offer) offer.note += `; a home-equity line up to ${pct(sec.max_ltv as number)} LTV is also available`;
  return { checks, offer, applicable: true };
}

function evalBusinessCard(p: LenderPolicy, ctx: Ctx): Evaluated {
  const r = p.decisionRules;
  const revenue = ctx.get("annual_business_revenue");
  const months = ctx.get("months_in_business");
  if (revenue === undefined && months === undefined) {
    return { checks: [], applicable: false, notApplicableReason: "No business on file." };
  }
  const checks: Check[] = autoDeclines(ctx, r, {});
  const deposits = ctx.get("cibc_deposit_balance") ?? 0;
  const primary = ctx.get("primary_business_account_at_cibc") ?? 0;
  let minScore = num(r, "min_principal_credit_score")!;
  const relScore = num(r, "min_principal_credit_score_if_relationship");
  const scoreChk = (() => {
    if (relScore !== undefined && deposits >= 25000) {
      minScore = relScore;
      const c = scoreMin(ctx, minScore, "Principal credit score");
      c.detail += ` (relationship floor: ${money(deposits)} deposited at CIBC)`;
      c.factKeys.push("cibc_deposit_balance");
      return c;
    }
    return scoreMin(ctx, minScore, "Principal credit score");
  })();
  checks.push(scoreChk);
  let minMonths = num(r, "min_months_in_business")!;
  const relMonths = num(r, "min_months_in_business_if_primary_account");
  const monthsChk = (() => {
    if (relMonths !== undefined && primary >= 1) {
      minMonths = relMonths;
      const c = minCheck("Months in business", months, minMonths, "months_in_business", (n) => `${n} months`);
      c.factKeys.push("primary_business_account_at_cibc");
      return c;
    }
    return minCheck("Months in business", months, minMonths, "months_in_business", (n) => `${n} months`);
  })();
  checks.push(monthsChk);
  checks.push(minCheck("Business revenue", revenue, num(r, "min_annual_business_revenue")!, "annual_business_revenue"));
  const debt = ctx.get("business_debt");
  checks.push(
    maxCheck("Business debt / revenue", debt !== undefined && revenue ? debt / revenue : undefined, num(r, "max_business_debt_to_revenue")!, ["business_debt", "annual_business_revenue"], "business debt not on file"),
  );
  const cl = obj(r, "credit_limit")!;
  const assets = ctx.get("investable_assets_at_cibc") ?? 0;
  const formula = (assets >= 250000 && (cl.formula_if_aum_ge_250000 as string)) || (cl.formula as string) || (cl.formula_default as string);
  let offer: LenderCheck["offer"];
  if (revenue !== undefined && formula) {
    const lim = Math.max(Math.min(parseLinear(formula).apply(revenue), cl.cap as number), cl.floor as number);
    const secured = typeof r.security_deposit_required_if === "string" ? scoreTest(ctx, parseCondition(r.security_deposit_required_if).op, parseCondition(r.security_deposit_required_if).value) : null;
    offer = {
      kind: secured?.outcome ? "secured business card" : "business card",
      limit: lim,
      note: [`${formula}, capped at ${money(cl.cap as number)}`, secured?.outcome === null ? "security deposit depends on exact score" : "", r.personal_guarantee_required ? "personal guarantee required" : ""].filter(Boolean).join("; "),
    };
  }
  return { checks, offer, applicable: true };
}

const EVALUATORS: Record<LenderProduct, (p: LenderPolicy, ctx: Ctx) => Evaluated> = {
  mortgage: evalMortgage,
  personal_line_of_credit: evalPlc,
  business_credit_card: evalBusinessCard,
};

function evaluateOnce(policy: LenderPolicy, facts: Facts) {
  const ctx = new Ctx(facts);
  const ev = EVALUATORS[policy.product](policy, ctx);
  return { ev, decision: decide(ev.checks), used: ctx.used };
}

export function evaluatePolicy(policy: LenderPolicy, facts: Facts): LenderCheck | null {
  const { ev, decision, used } = evaluateOnce(policy, facts);
  if (!ev.applicable) return null;
  const failing = ev.checks.filter((c) => c.outcome === "fail").map((c) => c.rule);
  const unknown = ev.checks.filter((c) => c.outcome === "unknown").map((c) => `${c.rule} (${c.detail})`);
  const summary =
    decision === "approve"
      ? `Meets ${policy.bank} ${policy.product.replace(/_/g, " ")} policy v${policy.version}.`
      : decision === "decline"
        ? `Fails: ${failing.join("; ")}.`
        : `Needs information: ${unknown.join("; ")}.`;
  // Counterfactual influence: drop each memory-backed fact the decision used and recompute.
  const pivotalFacts: PivotalFact[] = [];
  for (const key of used) {
    const without: Facts = { ...facts };
    delete without[key];
    const alt = evaluateOnce(policy, without);
    const altDecision: Decision = alt.ev.applicable ? alt.decision : "refer";
    if (altDecision !== decision) {
      pivotalFacts.push({ factKey: key, memoryId: facts[key].memoryId, statement: facts[key].statement, decisionWithout: altDecision });
    }
  }
  return {
    policyId: policy._id,
    bank: policy.bank,
    product: policy.product,
    policyVersion: policy.version,
    decision,
    summary,
    checks: ev.checks,
    offer: decision === "decline" ? undefined : ev.offer,
    factsUsed: [...used].map((k) => ({ key: k, value: facts[k].value, memoryId: facts[k].memoryId, version: facts[k].version })),
    pivotalFacts,
  };
}

/** Which products a request is about. No product named → every product the facts support. */
export function productsForRequest(request: string): LenderProduct[] {
  const t = request.toLowerCase();
  const out: LenderProduct[] = [];
  if (/mortgage|home purchase|move-up|rental purchase/.test(t)) out.push("mortgage");
  if (/line of credit|\bloc\b|\bplc\b|heloc|credit line/.test(t)) out.push("personal_line_of_credit");
  if (/business card|credit card|\bcard\b/.test(t)) out.push("business_credit_card");
  return out.length ? out : ["mortgage", "personal_line_of_credit", "business_credit_card"];
}

export function evaluateAll(policies: LenderPolicy[], facts: Facts, products: LenderProduct[]): LenderCheck[] {
  const current = policies.filter((p) => p.status === "current" && products.includes(p.product));
  const order = ["mortgage", "personal_line_of_credit", "business_credit_card"];
  return current
    .sort((a, b) => order.indexOf(a.product) - order.indexOf(b.product) || a.bank.localeCompare(b.bank))
    .map((p) => evaluatePolicy(p, facts))
    .filter((c): c is LenderCheck => c !== null);
}
